import{t as e}from"./api-7M9YWvHU.js";var t={async getAchievements(){return(await e.get(`/academy/achievements`)).data.achievements},async getBadges(){return(await e.get(`/academy/badges`)).data.badges},async getMilestones(){return(await e.get(`/academy/milestones`)).data.milestones},async getAchievementsAdmin(){return(await e.get(`/dams/achievements`)).data.achievements},async createAchievement(t){return(await e.post(`/dams/achievements`,t)).data.achievement},async updateAchievement(t,n){return(await e.put(`/dams/achievements/${t}`,n)).data.achievement},async deleteAchievement(t){await e.delete(`/dams/achievements/${t}`)},async getBadgesAdmin(){return(await e.get(`/dams/badges`)).data.badges},async createBadge(t){return(await e.post(`/dams/badges`,t)).data.badge},async updateBadge(t,n){return(await e.put(`/dams/badges/${t}`,n)).data.badge},async deleteBadge(t){await e.delete(`/dams/badges/${t}`)}};export{t};